const int MOD = 998244353;

long long fastExp(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long a, int m) {
    return fastExp(a, m - 2);
}

